package org.eclipse.kura.core.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.eclipse.kura.message.KuraBirthPayload;
import org.eclipse.kura.message.KuraBirthPayload.KuraBirthPayloadBuilder;
import org.junit.Test;

public class KuraBirthPayloadModemEidTest {

    private static final String EID = "89049032000001000000123456789012";

    private KuraBirthPayloadBuilder builder;
    private KuraBirthPayload birthPayload;

    @Test
    public void shouldExposeModemEidSetOnTheBuilder() {
        givenBirthPayloadBuilder();
        givenModemEid(EID);

        whenBirthPayloadIsBuilt();

        thenModemEidIs(EID);
        thenModemEidMetricIs(EID);
    }

    @Test
    public void shouldNotExposeModemEidWhenNotSetOnTheBuilder() {
        givenBirthPayloadBuilder();

        whenBirthPayloadIsBuilt();

        thenModemEidIsNotPresent();
    }

    private void givenBirthPayloadBuilder() {
        this.builder = new KuraBirthPayloadBuilder().withDisplayName("displayName").withJdkVendorVersion("jdkVendorVersion");
    }

    private void givenModemEid(String eid) {
        this.builder.withModemEid(eid);
    }

    private void whenBirthPayloadIsBuilt() {
        this.birthPayload = this.builder.build();
    }

    private void thenModemEidIs(String expected) {
        assertEquals(expected, this.birthPayload.getModemEid());
        assertEquals("displayName", this.birthPayload.getDisplayName());
    }

    private void thenModemEidMetricIs(String expected) {
        assertEquals(expected, this.birthPayload.getMetric("modem_eid"));
    }

    private void thenModemEidIsNotPresent() {
        assertNull(this.birthPayload.getModemEid());
        assertNull(this.birthPayload.getMetric("modem_eid"));
        assertEquals("displayName", this.birthPayload.getDisplayName());
    }
}
